mapper.select:
SELECT
    (
        SELECT COALESCE(SUM(COALESCE(input_tokens, 0)), 0)
        FROM ai_conversation_turn
        WHERE deleted = 0 AND role = 'ASSISTANT' AND tenant_id = #{tenantId}
          AND create_time >= #{startTime} AND create_time < #{endTime}
    ) + (
        SELECT COALESCE(SUM(COALESCE(input_tokens, 0)), 0)
        FROM ai_workflow_execution
        WHERE deleted = 0 AND tenant_id = #{tenantId}
          AND end_time >= #{startTime} AND end_time < #{endTime}
    ) AS inputTokens,
    (
        SELECT COALESCE(SUM(COALESCE(output_tokens, 0)), 0)
        FROM ai_conversation_turn
        WHERE deleted = 0 AND role = 'ASSISTANT' AND tenant_id = #{tenantId}
          AND create_time >= #{startTime} AND create_time < #{endTime}
    ) + (
        SELECT COALESCE(SUM(COALESCE(output_tokens, 0)), 0)
        FROM ai_workflow_execution
        WHERE deleted = 0 AND tenant_id = #{tenantId}
          AND end_time >= #{startTime} AND end_time < #{endTime}
    ) AS outputTokens,
    (
        SELECT COUNT(*)
        FROM ai_conversation_turn
        WHERE deleted = 0 AND role = 'USER' AND tenant_id = #{tenantId}
          AND create_time >= #{startTime} AND create_time < #{endTime}
    ) AS conversationCount,
    (
        SELECT COUNT(*)
        FROM (
            SELECT user_id
            FROM ai_conversation_turn
            WHERE deleted = 0 AND role = 'USER' AND tenant_id = #{tenantId}
              AND user_id IS NOT NULL
              AND create_time >= #{startTime} AND create_time < #{endTime}
            UNION
            SELECT user_id
            FROM ai_workflow_execution
            WHERE deleted = 0 AND tenant_id = #{tenantId}
              AND user_id IS NOT NULL
              AND COALESCE(input_tokens, 0) + COALESCE(output_tokens, 0) > 0
              AND end_time >= #{startTime} AND end_time < #{endTime}
        ) active_users
    ) AS activeUserCount

SELECT
    token_totals.user_id AS userId,
    COALESCE((
        SELECT n.create_name
        FROM ai_conversation_turn n
        WHERE n.deleted = 0
          AND n.tenant_id = #{tenantId}
          AND n.user_id = token_totals.user_id
          AND n.create_name IS NOT NULL
          AND n.create_name != ''
          AND n.create_time >= #{startTime}
          AND n.create_time < #{endTime}
        ORDER BY n.create_time DESC, n.id DESC
        LIMIT 1
    ), (
        SELECT w.create_name
        FROM ai_workflow_execution w
        WHERE w.deleted = 0
          AND w.tenant_id = #{tenantId}
          AND w.user_id = token_totals.user_id
          AND w.create_name IS NOT NULL
          AND w.create_name != ''
          AND w.end_time >= #{startTime}
          AND w.end_time < #{endTime}
        ORDER BY w.end_time DESC, w.id DESC
        LIMIT 1
    )) AS userName,
    COALESCE(SUM(token_totals.input_tokens), 0) AS inputTokens,
    COALESCE(SUM(token_totals.output_tokens), 0) AS outputTokens,
    COALESCE(SUM(token_totals.input_tokens + token_totals.output_tokens), 0) AS totalTokens,
    (
        SELECT COUNT(*)
        FROM ai_conversation_turn c
        WHERE c.deleted = 0 AND c.role = 'USER' AND c.tenant_id = #{tenantId}
          AND c.user_id = token_totals.user_id
          AND c.create_time >= #{startTime} AND c.create_time < #{endTime}
    ) AS conversationCount
FROM (
    SELECT user_id, COALESCE(input_tokens, 0) AS input_tokens,
           COALESCE(output_tokens, 0) AS output_tokens
    FROM ai_conversation_turn
    WHERE deleted = 0 AND role = 'ASSISTANT' AND tenant_id = #{tenantId}
      AND user_id IS NOT NULL
      AND create_time >= #{startTime} AND create_time < #{endTime}
    UNION ALL
    SELECT user_id, COALESCE(input_tokens, 0) AS input_tokens,
           COALESCE(output_tokens, 0) AS output_tokens
    FROM ai_workflow_execution
    WHERE deleted = 0 AND tenant_id = #{tenantId}
      AND user_id IS NOT NULL
      AND end_time >= #{startTime} AND end_time < #{endTime}
) token_totals
GROUP BY token_totals.user_id
HAVING SUM(token_totals.input_tokens + token_totals.output_tokens) > 0
ORDER BY totalTokens DESC, inputTokens DESC, outputTokens DESC, token_totals.user_id ASC
LIMIT #{limit}
